args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?person ?personLabel (COALESCE(?d1, ?d2) AS ?birthDate) WHERE {
  VALUES ?person { dbr:Ausaf_Ali dbr:Steven_Perry }
  OPTIONAL { ?person dbo:birthDate ?d1 }
  OPTIONAL { ?person dbp:birthDate ?d2 }
  OPTIONAL { ?person rdfs:label ?personLabel . FILTER(lang(?personLabel) = 'en') }
} ORDER BY ?personLabel

PREFIX dbo: <http://dbpedia.org/ontology/>
